import{_ as p,a0 as i,w as d,s as l,I as o,x as s,a1 as t,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux 下 SSH 命令实例指南 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下 SSH 命令实例指南 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下 SSH 命令实例指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下 SSH 命令实例指南 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 A Pocket Guide for Linux ssh Command with Examples","title":"Linux 下 SSH 命令实例指南","tag":"201409","desc":""},"relativePath":"201409/20140819 A Pocket Guide for Linux ssh Command with Examples.md","filePath":"[post].md"}'),h={name:"201409/20140819 A Pocket Guide for Linux ssh Command with Examples.md"};function m(u,e,S,x,f,g){const n=i("Link");return d(),l("div",null,[e[19]||(e[19]=o("h1",{id:"linux-下-ssh-命令实例指南",tabindex:"-1"},[s("Linux 下 SSH 命令实例指南 "),o("a",{class:"header-anchor",href:"#linux-下-ssh-命令实例指南","aria-label":"Permalink to “Linux 下 SSH 命令实例指南”"},"​")],-1)),e[20]||(e[20]=o("p",null,"如果你已经在IT圈内混了很长时间, 应该对 SSH 这个了不起的工具及其安全特性有所耳闻吧. 本教程可以让你在短时间内掌握通过 SSH 安全便利地连接到远程计算机的技术.",-1)),o("p",null,[e[1]||(e[1]=s("如果你对 SSH 还没什么概念, 可以先访问 ",-1)),t(n,{href:"http://en.wikipedia.org/wiki/Secure_Shell"},{default:a(()=>[...e[0]||(e[0]=[s("维基百科",-1)])]),_:1}),e[2]||(e[2]=s(" 进行了解.",-1))]),e[21]||(e[21]=r(`<h3 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to “基本用法”">​</a></h3><p>最简单的 SSH 命令只需要指定用户名和主机名参数即可. 主机名可以是 IP 地址或者域名. 命令格式如下:</p><pre><code>$ ssh user@hostname
</code></pre><p>比如要在我的局域网内登录一个树莓派系统, 只需要简单的在命令行输入如下命令:</p><pre><code>$ ssh pi@10.42.0.47
</code></pre><p>命令中的 pi 和 10.42.0.47 分别是我的树莓派系统的用户名和局域网 IP 地址. 实际使用时主机名需要改成你的目标主机(局域网内或者远程)的 IP 地址.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/basic-ssh.png" alt="basic ssh"></p><p>如果你能够成功登陆, 那么下面的内容对你来说就轻而易举了.</p><h3 id="使用其他端口" tabindex="-1">使用其他端口 <a class="header-anchor" href="#使用其他端口" aria-label="Permalink to “使用其他端口”">​</a></h3><p>SSH 默认连接到目标主机的 22 端口上,但是由于各种原因你可能需要连接到其他端口.</p><pre><code>$ ssh -p 10022 user@hostname
</code></pre><p>如上命令就是通过添加参数 -p 指定端口号为 10022.</p><h3 id="远程执行命令" tabindex="-1">远程执行命令 <a class="header-anchor" href="#远程执行命令" aria-label="Permalink to “远程执行命令”">​</a></h3><p>有时在远程主机执行一条命令并显示到本地, 然后继续本地工作是很方便的. SSH 就能满足这个需求:</p><pre><code>$ ssh pi@10.42.0.47 ls -l
</code></pre><p>比如上面这个命令就会枚举远程主机的主目录内容并在本地显示. 是不是很酷? 你可以尝试下其他命令看看.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/remote-command.png" alt="remote command"></p><h3 id="挂载远程文件系统" tabindex="-1">挂载远程文件系统 <a class="header-anchor" href="#挂载远程文件系统" aria-label="Permalink to “挂载远程文件系统”">​</a></h3><p>另外一个很赞的基于 SSH 的工具叫 sshfs. sshfs 可以让你在本地直接挂载远程主机的文件系统.</p><pre><code>$ sshfs -o idmap=user user@hostname:/home/user ~/Remote
</code></pre><p>比如下面这条命令:</p><pre><code>$ sshfs -o idmap=user pi@10.42.0.47:/home/pi ~/Pi
</code></pre><p>该命令就将远程主机 pi 用户的主目录挂载到本地主目录下的 Pi 文件夹.</p>`,23)),o("p",null,[e[4]||(e[4]=s("要详细了解可以参考 ",-1)),t(n,{href:"http://linoxide.com/how-tos/sshfs-mount-remote-directories/"},{default:a(()=>[...e[3]||(e[3]=[s("sshfs 教程",-1)])]),_:1}),e[5]||(e[5]=s(".",-1))]),e[22]||(e[22]=r(`<h3 id="x11-图形界面" tabindex="-1">X11 图形界面 <a class="header-anchor" href="#x11-图形界面" aria-label="Permalink to “X11 图形界面”">​</a></h3><p>假如现在你想要在远程主机运行一个图形界面的程序, SSH 已经帮你想到了! 用前面提到的 SSH 基本命令加上参数 -X 连接到远程主机即可开启 X11 转发功能. 登录后你可能觉得没什么差别, 但是当你运行一个图形界面程序后就会发现其中的不同的.</p><pre><code>$ ssh -X pi@10.42.0.47

$ pistore
</code></pre><p>如果你想在运行图形界面程序的同时做些别的事情, 只需要简单地在命令末尾加一个 &amp; 符号.</p><pre><code>$ pistore&amp;
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/X11-forwarding.png" alt="X11 forwarding"></p><h3 id="转义字符" tabindex="-1">转义字符 <a class="header-anchor" href="#转义字符" aria-label="Permalink to “转义字符”">​</a></h3><p>SSH 提供了多样的转义字符功能. 用 SSH 连接到任意一台远程主机然后输入 ~? 你就可以看到支持的转义字符和功能说明列表. 以下例子展示了 <strong>~#</strong> 和 <strong>~C</strong> 的效果.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/escape-sequences.png" alt="escape sequences"></p><h3 id="配置-ssh" tabindex="-1">配置 SSH <a class="header-anchor" href="#配置-ssh" aria-label="Permalink to “配置 SSH”">​</a></h3><p>如果你需要改变 SSH 的配置, 请用你喜好的文本编辑器打开 <strong>/etc/ssh/sshd_config</strong> 进行编辑. 比如你想改变登陆的标语, 在配置文件中找到下面这行:</p><pre><code>#Banner none
</code></pre><p>删除 # 字符(取消该行的注释), 将 none 替换为包含你期望显示内容的文件地址. 修改后该行应该类似这样:</p><pre><code>Banner /etc/issue
</code></pre><p>在配置文件 <strong>/etc/ssh/sshd_config</strong> 中你还可以找到端口号, 空闲超时时间等配置项. 配置项大都比较容易理解, 但是保险起见在你修改一些不是很确定的配置项时最好参考下 SSH 的帮助文档.</p><h3 id="构建-ssh-密钥对" tabindex="-1">构建 ssh 密钥对 <a class="header-anchor" href="#构建-ssh-密钥对" aria-label="Permalink to “构建 ssh 密钥对”">​</a></h3><p>运行以下命令创建密钥对:</p><pre><code>$ ssh-keygen -t dsa
</code></pre><p>此命令会要求你输入密码(可以留空), 然后就会生成密钥并会显示一张该密钥对应的随机图.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/generate-key-pair.png" alt="generate key pair"></p><h3 id="寻找主机密钥" tabindex="-1">寻找主机密钥 <a class="header-anchor" href="#寻找主机密钥" aria-label="Permalink to “寻找主机密钥”">​</a></h3><p>在你准备添加密钥之前不妨先用以下命令看看是否已经添加了对应主机的密钥了.</p><pre><code>$ ssh-keygen -F 10.42.0.47
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/find-hostkey.png" alt="find hostkey"></p><h3 id="删除主机密钥" tabindex="-1">删除主机密钥 <a class="header-anchor" href="#删除主机密钥" aria-label="Permalink to “删除主机密钥”">​</a></h3><p>某些情况下, 比如主机地址更改或者不再使用某个密钥, 你就可能需要删除某个密钥.</p><pre><code>$ ssh-keygen -R 10.42.0.47
</code></pre><p>用以上命令就可删除. 这比手动在 <strong>~/.ssh/known_hosts</strong> 文件中删除要方便很多.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/remove-hostkey.png" alt="remove hostkey"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>通过以上的内容你应该可以轻松使用 SSH 了. SSH 还有很多功能值得你去发掘, 这就要看你的想象力了。</p><hr>`,32)),o("p",null,[e[7]||(e[7]=s("via: ",-1)),t(n,{href:"http://linoxide.com/linux-command/pocket-guide-linux-ssh-command/"},{default:a(()=>[...e[6]||(e[6]=[s("http://linoxide.com/linux-command/pocket-guide-linux-ssh-command/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=s("作者：",-1)),t(n,{href:"http://linoxide.com/author/bobbin/"},{default:a(()=>[...e[8]||(e[8]=[s("Bobbin Zachariah",-1)])]),_:1}),e[12]||(e[12]=s(" 译者：",-1)),t(n,{href:"https://github.com/henryfour"},{default:a(()=>[...e[9]||(e[9]=[s("henryfour",-1)])]),_:1}),e[13]||(e[13]=s(" 校对：",-1)),t(n,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[10]||(e[10]=[s("Caroline",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=s("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原创翻译，",-1)),t(n,{href:"http://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[s("Linux中国",-1)])]),_:1}),e[18]||(e[18]=s(" 荣誉推出",-1))])])}const T=p(h,[["render",m]]);export{k as __pageData,T as default};
